<?php
namespace App\Http\Controllers\Api;
use App\Http\Controllers\Controller; use App\Http\Controllers\Api\Concerns\HandlesCachedCrud; use App\Http\Resources\AcademicYearResource; use App\Models\AcademicYear; use Illuminate\Http\Request; use Illuminate\Validation\Rule;
class AcademicYearController extends Controller { 
    use HandlesCachedCrud; 
    private function rules(?AcademicYear $year=null): array { return ['name'=>['required','string','max:100',Rule::unique('academic_years')->ignore($year?->id)],'start_date'=>['required','date'],'end_date'=>['required','date','after:start_date'],'is_current'=>['sometimes','boolean']]; } public function index(){return $this->indexCrud(AcademicYear::class,AcademicYearResource::class);} public function store(Request $r){return $this->storeCrud($r,AcademicYear::class,AcademicYearResource::class,$this->rules());} public function show(AcademicYear $academicYear){return $this->showCrud($academicYear,AcademicYearResource::class);} public function update(Request $r,AcademicYear $academicYear){return $this->updateCrud($r,$academicYear,AcademicYearResource::class,$this->rules($academicYear));} public function destroy(AcademicYear $academicYear){return $this->destroyCrud($academicYear);} }
